create table d_ref_option_deal_pr(key_otc_trade_id string comment '内部合约ID',seq string comment '参与率序号',participation_rate string comment '参与率（%）',created_datetime string comment '创建时间',created_by string comment '创建人',updated_datetime string comment '修改时间',updated_by string comment '修改人',data_time string comment '【AI】数据时间') partitioned by (busi_date string) row format delimited fields terminated by ',' stored as textfile;
